{
  "name": "MP71025X可编程直流电源",
  "name_en": "MP71025X Programmable DC Power Supply",
  "manufacturer": "",
  "description": "MP71025X是一款实验室用可编程直流电源，用于为电子电路、器件和样品提供可调直流电压与电流，并支持输出开关、远端感测以及电压、电流、功率测量，适合台式测试、器件表征和一般电子实验。",
  "description_en": "The MP71025X is a laboratory programmable DC power supply used to provide adjustable DC voltage and current to electronic circuits, devices, and samples. It supports output on/off control, remote sensing, and measurement of voltage, current, and power for benchtop testing, device characterization, and general electronics lab work.",
  "tag_hints": [
    "programmable DC power supply",
    "benchtop PSU",
    "voltage and current sourcing",
    "remote sense",
    "electrical measurements",
    "electronics testing"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电源以开始实验使用。",
      "description_en": "Initialize the power supply for operation."
    },
    {
      "action_name": "auto-lock_commands",
      "description": "锁定或解锁设备控制。",
      "description_en": "Lock or unlock device controls."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量输出电流。",
      "description_en": "Measure the output current."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量输出功率。",
      "description_en": "Measure the output power."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量输出电压。",
      "description_en": "Measure the output voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "启用或禁用远端感测电压补偿。",
      "description_en": "Enable or disable remote-sense voltage compensation."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置输出电流限值。",
      "description_en": "Set the output current limit."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置输出电压。",
      "description_en": "Set the output voltage."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源输出。",
      "description_en": "Turn the power output on or off."
    }
  ]
}

